import json,hashlib,urllib.request,subprocess
from pathlib import Path
R=Path('/mnt/c/kidsmap');Q=R/'.tmp/m11-full-r1';O=R/'docs/qa/module11-repair-2026-10-18-pc-r1';assert 'pypdf==6.20.1' in (R/'requirements.txt').read_text();data=json.load(urllib.request.urlopen('https://pypi.org/pypi/pypdf/6.20.1/json',timeout=30));wheel=next(x for x in data['urls'] if x['filename'].endswith('py3-none-any.whl'));dest=Q/wheel['filename'];assert not dest.exists();urllib.request.urlretrieve(wheel['url'],dest);assert hashlib.sha256(dest.read_bytes()).hexdigest()==wheel['digests']['sha256'];target=Q/'test-dependencies';assert not target.exists();cmd=['docker','exec','m11full-r1-app','python','-m','pip','install','--no-index','--no-deps','--target',str(target),str(dest)];p=subprocess.run(cmd,capture_output=True,text=True);(Q/'pypdf-install.log').write_text(p.stdout+p.stderr);assert p.returncode==0,p.stderr[-500:];(O/'evidence/dependency-repair.json').write_text(json.dumps({'requirement':'pypdf==6.20.1','source':'https://pypi.org/pypi/pypdf/6.20.1/json','wheel_SHA256_verified':True,'installation':'owned writable QA target only, no shared image/host/prod changes','target':str(target),'exit':0},indent=2));print('Exact declared pypdf6.20.1 installed into owned QA target, verified official wheelSHA.')
